Definition setec_chk (code : Z) (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (BLi BLj : CA.blocks) : option CH2.cinfo := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S50}:!1,H,6!1,H#7!2+B+^\+3|40;$code;R+3$c;R+^X$ps;R+^Y$cj;R+^X$BLi;R'^Z$BLj;R'^Z&regs;R!1'^[#4!1+K+^\-^6RN$~R+^6!1+^C+_3!2'_4!2'_4!2'_5!4'2+^\0#11'^4!2'_5!4'2+^\};#112!2'_6#2#32!<'_;'^9'^:!1,>|800;,4#3!3,A!2+B3+^\!4,D3+^\!4,D+^\+3'^4,6!1,H!1,>4'_>!3'_?'^4,62!2,^H+^\'^4#6#5#4#3!1,_=+_3").
Definition setec_any (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (BLi BLj : CA.blocks) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S00$c;R+^X$ps;R+^Y$cj;R+^X$BLi;R'^Z$BLj;R'^Z!3'_@+3$code;R+3-^CRN$x;R!1+^C+_3+^6!6'_A#1#6#5#4#3#22$ci;R+_3!2'_B'^9!1'_C#1,^1'_D").
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  (CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 &&
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      if (Z.eqb pc POP || Z.eqb pc SETEC)%bool then
        (Z.eqb (SR.ps_pc ps) pc &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj => if Z.eqb pc POP then (Nat.eqb i 0 && Nat.eqb j JPOP && match pop_chk c ps cj (nth i G.BLS []) (nth j G.BLS []) with
                                                                                         | Some ci => (Nat.eqb (CC.cp_nx cj) (CH2.ci_nx ci + 1 + APC.NCS) && Nat.leb GT.NF (CH2.ci_nx ci))%bool | None => false end)%bool
                                  else ((Nat.eqb i 0 || Nat.eqb i JPOP) && negb (Nat.eqb j 0) && negb ((Nat.eqb j JPOP || Nat.eqb j JVIS)%bool) && setec_any c ps cj (nth i G.BLS []) (nth j G.BLS []))%bool
                     | None => false end
         | None => false end)%bool
      else if Z.eqb pc VIS then
        (Z.eqb (SR.ps_pc ps) pc && Nat.eqb i JPOP && PB.has cells (KRange (EVar 41) 1 1025) &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj => (Nat.eqb j JVIS && match VBX.vis_chk GT.NF G.HDECL Vb c ps cj (nth i G.BLS []) (nth j G.BLS []) with Some ci => true | None => false end)%bool
                     | None => false end
         | None => false end)%bool
      else (PB.exit_base_chk GT.NF RETPC c ps &&
            if Nat.eqb i JVIS then
              (* [comment removed for export] *)
              (PB.has cells (KWord (SA Eb 0) 4 (ELit 0)) && PB.has cells (KRange GX KIND KIND) && PB.has cells (KRange (EVar 41) 1 1025) &&
               ((view_chk cells LVLM1 (ELit 2) (ELit 1) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (EVar 41) 1 1))
                || (view_chk cells LVLM1 (ELit 7) (ELit 1) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (APC.eaddz (EVar 41) (-2)) 0 1023))))
            else
              (* [comment removed for export] *)
              (negb (Nat.eqb i 0) && negb (Nat.eqb i JPOP) && existsb (fun code => PB.has cells (KWord (SA Eb 0) 4 (ELit code))) CODES && PB.has cells (KWord (SA Eb 8) 8 (ELit PML.OBJ_JSON_CATEGORY)) &&
               (view_chk cells (EVar 41) (EVar 42) (ELit 0) (EVar 38) SEND0 SCEND0
                || (view_chk cells (EVar 41) GX (ELit 0) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (EVar 41) 1 1025)))))%bool
  end)%bool.
Lemma leaf_ok : CH2.leaves_all G.CPS G.TAGS leaf_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,J+^6,^7!3+Y+^6!3'_E'^<'^='_F,^7").
Qed.
(* [comment removed for export] *)
Definition GXN : nat := (CC.cp_nx (nth JPOP G.CPS G.cp0) - APC.NCS - 1)%nat.
Definition WARR : bool := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00,^1").
(* [comment removed for export] *)
Definition wsetec_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc =>
      if Z.eqb pc SETEC then
        if Nat.eqb i 0 then PB.has (SR.ps_cells ps) (KRange (EVar 41) 0 0)
        else match CH2.ret_of G.RETS i k with
             | Some j => match nth_error G.CPS j with
                         | Some cj => forallb (fun code => match setec_chk code c ps cj (nth i G.BLS []) (nth j G.BLS []) with
                                                        | Some ci => Nat.leb (CC.cp_nx c) (CH2.ci_nx ci) | None => true end) CODES
                         | None => false end
             | None => false end
      else true
  | _ => true
  end.
Lemma wsetec_ok : CH2.leaves_all G.CPS G.TAGS wsetec_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,J+^6,^7!3+Y+^6!3'_E'^<'^='_G,^7").
Qed.
(* [comment removed for export] *)
Definition werr_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  match t with
  | CC.TOther pc =>
      if (Nat.eqb i 0 || Nat.eqb i JPOP || Nat.eqb i JVIS)%bool then true
      else (APC.expr_vars_lt (CC.cp_nx c) GX &&
            forallb (fun code => negb (PB.has cells (KWord (SA Eb 0) 4 (ELit code))) ||
               (((code =? SPTW.EC_CLEVEL WARR) && PB.has cells (KRange (EVar 41) 0 0))
                || (PB.has cells (KRange (EVar 41) 1 1025) && PB.has cells (KRange GX 0 255) &&
                    SPTW.adm_all GXN cells 0 256 (fun p => negb (p =? SPTW.EC_KIND WARR) && (if p =? SPTW.EC_OTHER WARR then code =? SPTW.EC_COTHER WARR else code =? SPTW.EC_CLEVEL WARR)))))
              CODES)%bool
  | _ => true
  end.
